import os
import hashlib

def calculate_checksum(data):
    """Verilen verinin SHA-256 sağlama toplamını hesaplar."""
    return hashlib.sha256(data).hexdigest()

def process_files_in_directory(directory_path, output_file_path):
    """Belirtilen klasördeki tüm dosyalar için işlem yapar."""
    with open(output_file_path, 'w') as output_file:
        output_file.write("Dosya Adı,Okunan Bayt Sayısı,Hash\n")

        for root, _, files in os.walk(directory_path):
            for file_name in files:
                file_path = os.path.join(root, file_name)
                try:
                    with open(file_path, 'rb') as file:
                        data = file.read()
                        byte_count = len(data)
                        checksum = calculate_checksum(data) if data else "0"

                        # Sağlama toplamı 0 ise arabellek boş
                        if checksum == "0":
                            print(f"{file_path} boş dosya.")

                        # Dosya bilgilerini çıktı dosyasına yaz
                        output_file.write(f"{file_name},{byte_count},{checksum}\n")

                except Exception as e:
                    print(f"{file_path} okunamadı: {e}")

# Kullanım örneği
if __name__ == "__main__":
    input_directory = "input_folder"  # İşlem yapılacak klasör
    output_file = "output_summary.csv"  # Sonuçların kaydedileceği dosya
    process_files_in_directory(input_directory, output_file)
